run(`function recoveryAcross(key,before,after,extra={}){
 s={...defaults,mode:'reentrant',shape:'double',liquid:17,fs:.04,pitch:100,height:80,...extra,[key]:before,pressure:0};
 collapsed=false;collapseEvent=null;loadPair();syncTaper();
 const start=suspension();s[key]=after;syncTaper();const end=suspension();
 const lower=start.critical-start.load,upper=end.critical-end.load;
 if(!(upper>lower&&upper>0))return false;
 const pressure=(Math.max(0,lower)+upper)/2;
 s[key]=before;s.pressure=pressure;syncTaper();update();if(!collapsed)return false;
 s[key]=after;syncTaper();update();
 return !collapsed&&collapseEvent===null&&!textureGeometry().filled&&model().name==='Cassie–Baxter'&&$('equation').innerHTML.includes('f<sub>solid</sub>')&&Math.abs(foot-cap(s.V,model().theta).a)<1e-10;
}`);
