check('Rough modes default to the equation angle with zero macroscopic retention',"['wenzel','cassie','reentrant'].every(mode=>{freshRough(mode);const theta=model().theta,initial=foot;stepVolume(5.2);update();const q=quantities();return !s.roughHysteresis&&q.theta===theta&&q.ret===0&&q.alpha===0&&foot!==initial&&!$('modeControls').innerHTML.includes('id=\"ctl-hyst\"')&&$('modeControls').innerHTML.includes('id=\"roughHysteresis\"');})");
check('Enabled rough modes pin the footprint and change the current volume angle',"['wenzel','cassie','reentrant'].every(mode=>{freshRough(mode);setRoughHysteresis(true);const initial=foot,theta=model().theta;stepVolume(5.1);update();const q=quantities();return lineStatus==='Pinned'&&foot===initial&&q.theta>theta&&q.theta<q.b.A&&Math.abs(q.c.a-initial)<1e-10&&$('modeControls').innerHTML.includes('id=\"ctl-hyst\"');})");
check('All rough modes advance, reverse at a fixed footprint and then recede',"['wenzel','cassie','reentrant'].every(mode=>{freshRough(mode,true);stepVolume(30);update();const advancing=lineStatus==='Advancing'&&Math.abs(quantities().theta-bounds(model().theta).A)<1e-9,radius=foot;stepVolume(29.9);update();const reversing=lineStatus==='Pinned'&&foot===radius;stepVolume(.2);update();return advancing&&reversing&&lineStatus==='Receding'&&Math.abs(quantities().theta-bounds(model().theta).R)<1e-9&&foot<radius;})");
check('Disabling rough hysteresis clears angle memory and restores the equation',"['wenzel','cassie','reentrant'].every(mode=>{freshRough(mode,true);stepVolume(5.1);update();if(quantities().theta===model().theta)return false;setRoughHysteresis(false);const q=quantities();return q.theta===model().theta&&q.ret===0&&lineStatus==='Equilibrated'&&Math.abs(foot-cap(s.V,q.theta).a)<1e-10&&!$('modeControls').innerHTML.includes('id=\"ctl-hyst\"');})");
check('Rough hysteresis controls tilt retention as well as volume pinning',"['wenzel','cassie','reentrant'].every(mode=>{freshRough(mode);s.tilt=1;update();const free=quantities().sliding;setRoughHysteresis(true);const held=quantities();return free&&!held.sliding&&held.ret>held.force;})");
check('Geometry changes invalidate volume memory around an obsolete Wenzel reference',"(()=>{freshRough('wenzel',true);stepVolume(5.1);update();s.r=1.2;update();return lineStatus==='Equilibrated'&&quantities().theta===model().theta&&Math.abs(foot-cap(s.V,model().theta).a)<1e-10;})()");
check('The toggle and presets preserve microscopic limits and deliberate filling',"(()=>{preset('oil');const prediction=suspension();collapsed=true;collapseEvent={reason:'Texture deliberately filled',load:prediction.load,critical:prediction.critical,snapshot:microSnapshot(prediction),settings:survivalSettings()};resetFoot();update();const event=collapseEvent,before=survivalSettings(),critical=suspension().critical;setRoughHysteresis(true);setPinningPreset(35);setRoughHysteresis(false);return collapsed&&collapseEvent===event&&before===survivalSettings()&&suspension().critical===critical&&model().name==='Wenzel';})()");
check('Collapse and recovery reset enabled volume memory to the new equation',"(()=>{preset('oil');setRoughHysteresis(true);stepVolume(5.1);update();s.pressure=5000;update();const filled=collapsed&&quantities().theta===model().theta;s.pressure=0;update();return filled&&!collapsed&&model().name==='Cassie–Baxter'&&quantities().theta===model().theta;})()");
check('Model explanations retain the reference equation and show optional current-angle limits',"(()=>{freshRough('cassie');const off=$('hysteresisNote').innerHTML==='Hysteresis neglected.';setRoughHysteresis(true);stepVolume(5.1);update();const on=$('hysteresisNote').innerHTML.includes('Reference')&&$('hysteresisNote').innerHTML.includes('Current angle may vary while pinned.')&&$('equation').innerHTML.includes('f<sub>solid</sub>');return off&&on&&localizedText('Include hysteresis')==='Include hysteresis'&&german['Include hysteresis']==='Hysterese berücksichtigen';})()");
check('CSV records effective hysteresis and separates current and reference angles',"(()=>{freshRough('wenzel');record();const off=notebook.at(-1);setRoughHysteresis(true);stepVolume(5.1);update();record();const on=notebook.at(-1);return off.hysteresis_input_deg===0&&!off.rough_hysteresis_enabled&&off.delta_apparent_deg===off.delta_reference_deg&&on.rough_hysteresis_enabled&&on.hysteresis_input_deg===12&&on.delta_apparent_deg>on.delta_reference_deg;})()");
check('The sticky example explicitly enables pinning while ordinary rough examples start without it',"(()=>{preset('sticky');const sticky=s.roughHysteresis&&effectiveHysteresis()===65;preset('lotus');const lotus=!s.roughHysteresis&&effectiveHysteresis()===0;preset('oil');return sticky&&lotus&&!s.roughHysteresis&&effectiveHysteresis()===0;})()");

run(`function rippleTestView(theta=108.5,tilt=0,lean=0,V=5,gpu=true){const v=framing(theta,V,lean,tilt,0);return {...v,tilt,lean,radius:v.cp.R*v.scale,cosTheta:Math.cos(rad(theta)),height:v.cp.h*v.scale,a:v.cp.a*v.scale,gpu};}
function studioHighlight(v){const co=Math.cos(rad(v.tilt)),si=Math.sin(rad(v.tilt)),rz=-Math.sqrt(1-.46**2-.57**2),nz=Math.sqrt((1+rz)/2),rx=co*(-.46)+si*(-.57),ry=-si*(-.46)+co*(-.57),nx=rx/(2*nz),ny=ry/(2*nz),p=rippleVector([nx,ny-v.lean*nx,nz]),ly=(p[1]+v.cosTheta)*v.radius,lx=p[0]*v.radius-v.lean*ly;return {x:v.x+co*lx-si*ly,y:v.y+si*lx+co*ly,p,ly};}`);
check('Reflection hit target follows the same tilted and sheared optical highlight',"[90,108.5,150,174].every(theta=>[-60,0,50].every(tilt=>[-.2,0,.2].every(lean=>{const v=rippleTestView(theta,tilt,lean),h=studioHighlight(v),hit=rippleSourceAt(h.x,h.y,v);return h.ly>0?hit===null:!!hit&&hit.every((x,i)=>Math.abs(x-h.p[i])<1e-9);})))");
check('Ripple ignores the ordinary drop body, substrate, outside space and absent drops',"(()=>{const v=rippleTestView();return rippleSourceAt(v.x,v.y+3,v)===null&&rippleSourceAt(v.x+2*v.radius,v.y-v.height,v)===null&&rippleSourceAt(v.x,v.y+v.cosTheta*v.radius,v)===null&&rippleSourceAt(0,0,null)===null&&rippleSourceAt(NaN,1,v)===null;})()");
check('SVG fallback highlight remains an accurate hidden target',"[-45,0,55].every(tilt=>{const v=rippleTestView(108.5,tilt,.12,5,false),cx=-.34*v.a+v.lean*v.height*.72,cy=-v.height*.7,dy=-v.height*.74-cy,co=Math.cos(rad(-28)),si=Math.sin(rad(-28)),lx=co*cx-si*dy,ly=si*cx+co*dy+cy,ct=Math.cos(rad(tilt)),st=Math.sin(rad(tilt));return !!rippleSourceAt(v.x+ct*lx-st*ly,v.y+st*lx+ct*ly,v);})");
check('Rippling changes no model, history, contact angle or microscopic limit',"(()=>{preset('oil');resetFoot();const q=quantities(),before=JSON.stringify([s,energy,foot,volumeTheta,history,collapsed,collapseEvent,suspension()]);rippleView=rippleTestView();const h=studioHighlight(rippleView),started=startSurfaceRipple(h.x,h.y);advanceRipple(.4);scene(q);return started&&!!surfaceRipple&&before===JSON.stringify([s,energy,foot,volumeTheta,history,collapsed,collapseEvent,suspension()])&&quantities().theta===q.theta;})()");
check('Curved fallback waves remain finite across droplet angles, sizes and tilt',"[15,60,108.5,160,179].every(theta=>[.2,5,30].every(V=>[-60,0,65].every(tilt=>{const v=rippleTestView(theta,tilt,.12,V,false),source=rippleVector([-.35,-.9,.3]);return [.01,.4,.9,1.5,2.19].every(age=>{const draw=rippleFallback(v,{source,age});return draw.includes('clip-path=\"url(#dropClip)\"')&&!/NaN|Infinity|undefined/.test(draw);});})))");
check('Ripple expires, can be retriggered, runs while paused and clears on a new drop',"(()=>{paused=true;rippleView=rippleTestView();const h=studioHighlight(rippleView);startSurfaceRipple(h.x,h.y);advanceRipple(.5);const alive=!!surfaceRipple;startSurfaceRipple(h.x,h.y);const retriggered=surfaceRipple.age===0;advanceRipple(rippleDuration+.01);const expired=surfaceRipple===null;startSurfaceRipple(h.x,h.y);resetFoot();paused=false;return alive&&retriggered&&expired&&surfaceRipple===null&&rippleView===null&&rippleFallback(rippleTestView(),{source:h.p,age:rippleDuration})==='';})()");

check('Ideal Model calculation evaluates inverse cosine and starts spreading on its own line',"(()=>{s={...defaults};collapsed=false;energy={sv:50,sl:25,lv:50};resetFoot();equation(quantities());const calculation=$('substitution').innerHTML;return calculation.includes('δ = cos<sup>−1</sup>(0.5000) ≈ 60.0°')&&calculation.includes('<br>S<sub>w</sub> = 50.0 − 25.0 − 50.0 = -25.0 mN/m.');})()");
check('Rough inverse-cosine steps evaluate the reference equation, including collapsed Wenzel',"(()=>{freshRough('cassie',true);stepVolume(5.1);update();const reference=model().theta,current=quantities().theta,suspended=$('substitution').innerHTML.includes('δ<sub>rough</sub> = cos<sup>−1</sup>')&&$('substitution').innerHTML.includes('≈ '+f(reference)+'°')&&current!==reference;energy={sv:40,sl:40,lv:72.8};collapsed=true;resetFoot();equation(quantities());return suspended&&$('equation').innerHTML.includes('A<sub>r</sub>')&&$('substitution').innerHTML.includes('≈ 90.0°');})()");
check('Infused Model calculation uses its effective tension in the numerical angle step',"(()=>{s={...defaults,mode:'lis'};collapsed=false;loadInfusedPair();equation(quantities());const z=lis(),calculation=$('substitution').innerHTML;return calculation.includes('γ<sub>eff</sub> = '+f(z.eff,2))&&calculation.includes('δ<sub>app</sub> = cos<sup>−1</sup>('+f(z.c,4)+') ≈ '+f(z.theta)+'°')&&calculation.includes('<br>S<sub>cloak</sub> = ');})()");
check('Numerical inverse cosine never fabricates an angle outside its domain',"(()=>{const rejected=[inverseCosineCalculation('δ',1.01,0),inverseCosineCalculation('δ',-1.01,null),inverseCosineCalculation('δ',0,null),inverseCosineCalculation('δ',NaN,90)].every(x=>x==='');const boundary=inverseCosineCalculation('δ',-1,180).includes('cos<sup>−1</sup>(-1) ≈ 180.0°'),near=inverseCosineCalculation('δ',Math.cos(rad(.1)),.1).includes('0.99999848');s={...defaults,mode:'wenzel',r:4};energy={sv:50,sl:25,lv:50};collapsed=false;resetFoot();equation(quantities());return rejected&&boundary&&near&&!$('substitution').innerHTML.includes('cos<sup>−1</sup>')&&!/NaN|Infinity/.test($('substitution').innerHTML);})()");

check('All six infused liquid pairs initialize low hysteresis and low roll-off without solid presets',"Object.keys(infusedPairs).every(key=>{s={...defaults,mode:'lis',liquid:+key};collapsed=false;loadInfusedPair();resetFoot();buildControls();update();const q=quantities(),controls=$('modeControls').innerHTML;return effectiveHysteresis()===.5&&q.ret>0&&q.alpha>0&&q.alpha<3&&controls.includes('data-key=\"lisHyst\" min=\"0\" max=\"5\" step=\"0.1\"')&&!controls.includes('data-pinning=')&&controls.includes('Literature-informed default: 0.5°');})");
check('Fine infused hysteresis clamps to range and changes retention without changing interfacial data',"(()=>{s={...defaults,mode:'lis',tilt:1};loadInfusedPair();resetFoot();const before=JSON.stringify([energy,s.oilAir,s.dropOil,s.liquid,s.solid]),angle=lis().theta;setInfusedHysteresis(-1);const free=s.lisHyst===0&&quantities().ret===0&&quantities().sliding;setInfusedHysteresis(9);const upper=quantities().ret;setInfusedHysteresis(.54);const lower=quantities().ret;setInfusedHysteresis(NaN);return free&&s.lisHyst===.5&&upper>lower&&lower>0&&lis().theta===angle&&before===JSON.stringify([energy,s.oilAir,s.dropOil,s.liquid,s.solid]);})()");
check('Infused literature assumptions and measured systems stay distinct in both languages',"(()=>{language='en';equation(quantities());const note=$('hysteresisNote').innerHTML;language='de';const caption=localizedText('Literature-informed default: 0.5°'),qualifier=localizedText('Literature-informed input, not pair-specific data.');language='en';return note.includes('not pair-specific data')&&caption.includes('Literaturgestützter')&&qualifier.includes('keine Messdaten')&&html.includes('1.9 ± 0.9°')&&html.includes('1.9 ± 0.5°')&&html.includes('13.1 ± 1.3°')&&html.includes('their measurements are not assigned to the Krytox 1506 model');})()");

check('Canvas material names track presets, Custom energies and German',"(()=>{language='en';s={...defaults,liquid:0,solid:0};loadPair();const presetNames=materialNames();editEnergy('lv',60);const customNames=materialNames();language='de';const germanNames=materialNames();language='en';return presetNames.liquid==='Water'&&presetNames.solid==='PTFE'&&customNames.liquid==='Custom'&&customNames.solid==='Custom'&&germanNames.liquid==='Benutzerdefiniert'&&germanNames.solid==='Benutzerdefiniert';})()");
check('Material visibility is independent of angles and preserves the experiment',"(()=>{s={...defaults};loadPair();resetFoot();materialLabelsEnabled=true;annotationsEnabled=false;const before=JSON.stringify([s,energy,foot,history,collapsed]),camera={x:180,y:0,w:540,h:470};const shown=materialOverlay(camera,390).includes('Liquid · Water')&&materialOverlay(camera,390).includes('Solid · PTFE');toggleMaterialLabels();const hidden=materialOverlay(camera,390)===''&&!annotationsEnabled;toggleMaterialLabels();annotationsEnabled=true;return shown&&hidden&&materialLabelsEnabled&&before===JSON.stringify([s,energy,foot,history,collapsed]);})()");
check('Microscopic phase labels follow the same independent visibility control',"(()=>{preset('oil');const p=suspension();materialLabelsEnabled=true;const shown=microDiagram(p,550,440);materialLabelsEnabled=false;const hidden=microDiagram(p,550,440);materialLabelsEnabled=true;return shown.includes('micro-material-labels')&&shown.includes('>Liquid</text>')&&shown.includes('>Solid</text>')&&!hidden.includes('micro-material-labels')&&!hidden.includes('>Gas</text>')&&hidden.includes('micro-contact');})()");
check('Footer anchors follow the visible camera edges at every split width',"[320,390,540,640,900].every(width=>[-42,0,42].every(offset=>{const camera={x:180+offset,y:0,w:width<650?540:900,h:width<650?470:430};const footer=sceneFooter(camera,width,100,100,23,width<650),xs=[...footer.matchAll(/<text x=\"([^\"]+)\"/g)].map(m=>+m[1]),ys=[...footer.matchAll(/ y=\"([^\"]+)\"/g)].map(m=>+m[1]);return xs.length===2&&xs[0]===camera.x+18&&xs[1]===camera.x+camera.w-18&&xs.every(x=>x>camera.x&&x<camera.x+camera.w)&&ys.every(y=>y<camera.h)&&(!footer.includes('Camera follows')||width>=650);}))");
check('Compact rough view reserves a separate footer strip below angle callouts',"(()=>{s={...defaults,mode:'reentrant'};loadPair();resetFoot();display.theta=150;display.V=5;display.tilt=23;display.lean=.1;display.slide=100;const attrs={};$('scene').setAttribute=(key,value)=>attrs[key]=value;$('scene').parentElement.clientWidth=540;scene(quantities());delete $('scene').parentElement.clientWidth;const camera=attrs.viewBox.split(' ').map(Number);return camera[2]>=540&&camera[3]===470&&$('scene').innerHTML.includes('class=\"scene-footer\"')&&$('scene').innerHTML.includes('y=\"459\"')&&$('annotationLayer').innerHTML.includes('material-labels')&&!$('scene').innerHTML.includes('Camera follows');})()");
check('Both on-canvas controls are unique, adjacent, default on and safe in mobile cards',"html.split('id=\"materialToggle\"').length===2&&html.includes('canvas-material-toggle{right:49px}')&&html.includes(\"for(const id of ['angleToggle','materialToggle'])\")&&html.includes(\"e.target.closest('#angleToggle,#materialToggle')\")&&html.includes('let materialLabelsEnabled=true;')&&german['Show liquid and solid labels'].includes('Festkörper')");

assert(!/compendium/i.test(html));checks++;
assert(!html.includes('id="modeSelect"')&&!html.includes('id="textureOpen"'));checks++;

assert(!/<(?:script|link|img)[^>]+(?:src|href)=['\"]https?:/i.test(html));checks++;
